import os
import json
import threading
from fastapi import FastAPI, HTTPException
from fastapi.responses import JSONResponse, Response
from pydantic import BaseModel

app = FastAPI()

DATA_DIR = "/workdir/data"
os.makedirs(DATA_DIR, exist_ok=True)

lock = threading.Lock()


class QueueCreate(BaseModel):
    name: str


class MessageCreate(BaseModel):
    content: str


def get_queue_path(name: str) -> str:
    return os.path.join(DATA_DIR, f"{name}.json")


def load_queue(name: str) -> list:
    path = get_queue_path(name)
    if not os.path.exists(path):
        return None
    with open(path, "r") as f:
        return json.load(f)


def save_queue(name: str, messages: list) -> None:
    path = get_queue_path(name)
    with open(path, "w") as f:
        json.dump(messages, f)


@app.post("/queues")
def create_queue(body: QueueCreate):
    with lock:
        path = get_queue_path(body.name)
        if os.path.exists(path):
            raise HTTPException(status_code=409, detail="Queue already exists")
        save_queue(body.name, [])
    return {"name": body.name}


@app.post("/queues/{name}/messages")
def send_message(name: str, body: MessageCreate):
    with lock:
        messages = load_queue(name)
        if messages is None:
            raise HTTPException(status_code=404, detail="Queue not found")
        messages.append(body.content)
        save_queue(name, messages)
    return {"content": body.content}


@app.get("/queues/{name}/messages")
def receive_message(name: str):
    with lock:
        messages = load_queue(name)
        if messages is None:
            raise HTTPException(status_code=404, detail="Queue not found")
        if len(messages) == 0:
            return Response(status_code=204)
        msg = messages.pop(0)
        save_queue(name, messages)
    return {"content": msg}


@app.get("/status")
def status():
    with lock:
        queues = []
        if os.path.exists(DATA_DIR):
            for fname in os.listdir(DATA_DIR):
                if fname.endswith(".json"):
                    queues.append(fname[:-5])
    return {"status": "ok", "queues": queues}


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
